# Some entries may have quick_check as list of strings or different keys. Normalize.
def normalize_quick_check(qc):
    norm=[]
    if isinstance(qc, list):
        for item in qc:
            if isinstance(item, dict):
                q=item.get("q") or item.get("question") or item.get("Q")
                a=item.get("a") or item.get("answer") or item.get("A")
                if q and a:
                    norm.append({"q":q, "a":a})
            elif isinstance(item, str):
                # split on — or -
                if "—" in item:
                    q,a=item.split("—",1)
                elif "-" in item:
                    q,a=item.split("-",1)
                else:
                    continue
                norm.append({"q":q.strip(), "a":a.strip()})
    return norm[:2]

